    await expect(canvas.getByText("cursor overlay sampler")).toBeInTheDocument();
    await expect(canvas.getByText("Copy telemetry")).toBeInTheDocument();
    await expect(canvas.getByText(/place camera-plane-reproject/)).toBeInTheDocument();
    await expect(canvas.getByText(/tangent-disc-visualizer on/)).toBeInTheDocument();
